import random

class Color:

    def __init__(self, r, g, b):
        self.r = r
        self.g = g
        self.b = b

    def toRGB(self):
        return (self.b, self.r, self.g)

    @staticmethod
    def fromHex(hexStr):
        if not isinstance(hexStr, str):
            return Color(255, 255, 255)
        s = hexStr.strip()
        if s.startswith('#'):
            s = s[1:]
        if len(s) != 6:
            return Color(255, 255, 255)
        for ch in s:
            if ch not in '0123456789abcdefABCDEF':
                return Color(255, 255, 255)
        r = int(s[0:2], 16)
        g = int(s[2:4], 16)
        b = int(s[4:6], 16)
        return Color(r, g, b)

    @staticmethod
    def generateRandom():
        return Color(random.randint(0, 255), random.randint(0, 255), random.randint(0, 255))

